# Duplicate Cluster Manager - runnable demo (JAH-ATK186-000001)
import difflib
RANK = 1
SIG = False
RECS = [('r1', 'Jon Smith', '10001'), ('r2', 'John Smith', '10001'), ('r3', 'Jane Doe', '90210'), ('r4', 'Jon Smyth', '10001')]  # (rec_id, name, zip)
def sim(a, b):
    return difflib.SequenceMatcher(None, a.lower(), b.lower()).ratio()
parent = {r[0]: r[0] for r in RECS}
def find(x):
    while parent[x] != x: parent[x] = parent[parent[x]]; x = parent[x]
    return x
def union(a, b): parent[find(a)] = find(b)
blocks = {}
for rid, name, zp in RECS: blocks.setdefault(zp, []).append((rid, name))
for members in blocks.values():
    for i in range(len(members)):
        for j in range(i+1, len(members)):
            if sim(members[i][1], members[j][1]) >= 0.8:
                union(members[i][0], members[j][0])
clusters = {}
for rid, _, _ in RECS: clusters.setdefault(find(rid), []).append(rid)
for root, members in clusters.items():
    if len(members) > 1: print("duplicate cluster:", members, "-> review queue")
if RANK >= 2:
    print("records:", len(RECS), "| clusters:", len(clusters), "| dup clusters:", sum(1 for m in clusters.values() if len(m) > 1))
if RANK >= 3:
    print("blocking keys used:", sorted(blocks))
if SIG:
    print("Signature lineage stamp: JAH-SIG-DED-" + "JAH-ATK186-000001")
print("record:", "JAH-ATK186-000001", "OK")

